$ErrorActionPreference = 'Stop'
$PSNativeCommandUseErrorActionPreference = $false
if (-not $IsWindows -or $PSVersionTable.PSVersion.Major -lt 7) { throw 'Windows pwsh 7 required' }
$base = '80d56fd1d6ef666eefe804be7f38de4742dcec43'
$actionPath = '.github/actions/run-duplicate-function-check/Invoke-DcoirDuplicateFunctionCheck.ps1'
$scanPath = '.github/scripts/Get-CollectorSourcePartFiles.ps1'
$sourceDir = 'project_sources/collector/source'
$checkout = [Environment]::GetEnvironmentVariable('DCOIR_REPO_ROOT','Machine')
$paths = @($actionPath,$scanPath,$sourceDir)
$actionBlob = git -C $checkout rev-parse "${base}:$actionPath"
if ($LASTEXITCODE -ne 0 -or $actionBlob -ne '6ba6bcc1b8f028399fa91d53f24901a7d20ae905') { throw 'Action baseline blob mismatch' }
$scanBlob = git -C $checkout rev-parse "${base}:$scanPath"
if ($LASTEXITCODE -ne 0 -or $scanBlob -ne '0ea8cacca705b03d147414233edee291a70eb410') { throw 'Scan helper baseline blob mismatch' }
$tree = @(git -C $checkout ls-tree -r $base -- @paths)
if ($LASTEXITCODE -ne 0 -or $tree.Count -lt 4 -or @($tree | Where-Object { $_ -notmatch '^100(644|755) blob [0-9a-f]{40}\t' }).Count -ne 0) { throw 'Archive source tree contains unexpected entry types' }
$start = (Get-Location).Path
$oldJson = [Environment]::GetEnvironmentVariable('DUPLICATE_FUNCTION_OUTPUT_JSON','Process')
$oldMarkdown = [Environment]::GetEnvironmentVariable('DUPLICATE_FUNCTION_OUTPUT_MARKDOWN','Process')
$scratch = Join-Path ([IO.Path]::GetTempPath()) ('dcoir-608-parity-' + [guid]::NewGuid().ToString('N'))
$owned = $false
function Write-ReportEvidence([string]$Case,[string]$Kind,[string]$Path) {
    $bytes = [IO.File]::ReadAllBytes($Path)
    if ($bytes.Length -eq 0) { throw "Empty report: $Case $Kind" }
    $hash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($bytes)).ToLowerInvariant()
    $buffer = [IO.MemoryStream]::new()
    try {
        $gzip = [IO.Compression.GZipStream]::new($buffer,[IO.Compression.CompressionMode]::Compress,$true)
        try { $gzip.Write($bytes,0,$bytes.Length) } finally { $gzip.Dispose() }
        $encoded = [Convert]::ToBase64String($buffer.ToArray())
        Write-Output "REPORT_EVIDENCE case=$Case kind=$Kind bytes=$($bytes.Length) sha256=$hash"
        Write-Output "REPORT_GZIP_BASE64 case=$Case kind=$Kind data=$encoded"
    } finally { $buffer.Dispose() }
}
try {
    if (Test-Path -LiteralPath $scratch) { throw 'Scratch path already exists' }
    New-Item -ItemType Directory -Path $scratch -ErrorAction Stop | Out-Null
    $owned = $true
    $archive = Join-Path $scratch 'baseline.zip'
    $repo = Join-Path $scratch 'repo'
    git -C $checkout archive --format=zip "--output=$archive" $base -- @paths
    if ($LASTEXITCODE -ne 0 -or -not [IO.File]::Exists($archive)) { throw 'Immutable baseline archive failed' }
    [IO.Compression.ZipFile]::ExtractToDirectory($archive,$repo)
    $action = Join-Path $repo $actionPath
    $scan = Join-Path $repo $scanPath
    # Verify the entire extracted tracked fixture against immutable blob identities.
    $filePaths = [System.Collections.Generic.List[string]]::new()
    $expectedBlobs = [System.Collections.Generic.List[string]]::new()
    foreach ($entry in $tree) {
        $entryMatch = [regex]::Match($entry,'^100(644|755) blob ([0-9a-f]{40})\t([A-Za-z0-9_./-]+)$')
        if (-not $entryMatch.Success) { throw 'Unexpected archive filename' }
        $relative = $entryMatch.Groups[3].Value
        if ($relative -match '(^|/)\.\.?(/|$)' -or $relative.StartsWith('/')) { throw 'Unexpected archive path' }
        $file = Join-Path $repo $relative
        $item = Get-Item -LiteralPath $file -Force -ErrorAction Stop
        if ($item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'Nonregular fixture source' }
        $filePaths.Add($file)
        $expectedBlobs.Add($entryMatch.Groups[2].Value)
    }
    # Use one Git process for the immutable blob comparison.
    $inputPaths = $filePaths.ToArray()
    $actualBlobs = @(git -C $checkout hash-object --no-filters -- @inputPaths)
    if ($LASTEXITCODE -ne 0 -or $actualBlobs.Count -ne $expectedBlobs.Count) { throw 'Archive hash verification failed' }
    for ($i=0; $i -lt $expectedBlobs.Count; $i++) { if ($actualBlobs[$i] -cne $expectedBlobs[$i]) { throw "Archive blob mismatch: $($filePaths[$i])" } }
    Set-Location -LiteralPath $repo
    . $scan
    $parts = @(Get-CollectorSourcePartFiles -RepositoryRoot $repo -ForValidation)
    if ($parts.Count -lt 2) { throw 'Insufficient tracked fixture parts' }
    $first = $parts[0]; $second = $parts[1]
    $firstBytes = [IO.File]::ReadAllBytes($first); $secondBytes = [IO.File]::ReadAllBytes($second)
    $strictUtf8 = [Text.UTF8Encoding]::new($false,$true)
    $null = $strictUtf8.GetString($firstBytes); $null = $strictUtf8.GetString($secondBytes)
    $seed = 'Get-DcoirIssue608Slice7ParitySentinel'
    $parseSeed = 'Get-DcoirIssue608Slice7ParityParseSentinel'
    $env:DUPLICATE_FUNCTION_OUTPUT_JSON = 'project_sources/collector/powershell_duplicate_function_report.json'
    $env:DUPLICATE_FUNCTION_OUTPUT_MARKDOWN = 'project_sources/collector/powershell_duplicate_function_report.md'
    $json = Join-Path $repo $env:DUPLICATE_FUNCTION_OUTPUT_JSON
    $markdown = Join-Path $repo $env:DUPLICATE_FUNCTION_OUTPUT_MARKDOWN
    $pwsh = (Get-Process -Id $PID).Path
    Write-Output "BASELINE=$base ACTION_BLOB=$actionBlob SCAN_BLOB=$scanBlob PWSH=$($PSVersionTable.PSVersion) TRACKED_FILES=$($expectedBlobs.Count) PARTS=$($parts.Count)"
    Write-Output "SEED_PARTS=$([IO.Path]::GetFileName($first))|$([IO.Path]::GetFileName($second))"
    $completed = 0
    foreach ($case in @('clean','duplicate','parse-failure')) {
        [IO.File]::WriteAllBytes($first,$firstBytes)
        [IO.File]::WriteAllBytes($second,$secondBytes)
        if ($case -eq 'duplicate') {
            $seedText = "`nfunction $seed { 'synthetic-parity' }`n"
            [IO.File]::AppendAllText($first,$seedText,[Text.UTF8Encoding]::new($false))
            [IO.File]::AppendAllText($second,$seedText,[Text.UTF8Encoding]::new($false))
        } elseif ($case -eq 'parse-failure') {
            [IO.File]::AppendAllText($first,"`nfunction $parseSeed {`n",[Text.UTF8Encoding]::new($false))
        }
        foreach ($path in @($json,$markdown)) {
            if ([IO.File]::Exists($path)) { [IO.File]::Delete($path) }
        }
        $output = @(& $pwsh -NoProfile -NonInteractive -File $action 2>&1)
        $exit = $LASTEXITCODE
        if (-not [IO.File]::Exists($json) -or -not [IO.File]::Exists($markdown)) {
            throw "Report missing in $case (exit=$exit): $($output -join ' ')"
        }
        $report = Get-Content -LiteralPath $json -Raw | ConvertFrom-Json
        if ($report.schema_version -ne 'dcoir_powershell_duplicate_function_report_v1' -or $report.summary.file_count -ne ($parts.Count + 1)) { throw "Report schema or target count mismatch: $case" }
        $dup = [int]$report.summary.duplicate_function_count
        $parse = [int]$report.summary.parse_failure_count
        if ($case -eq 'clean') {
            if ($exit -ne 0 -or $dup -ne 0 -or $parse -ne 0 -or -not $report.validation.success) { throw 'Clean baseline failed' }
        } elseif ($case -eq 'duplicate') {
            $seeded = @($report.duplicates | Where-Object { $_.function_name -eq $seed })
            if ($exit -ne 0 -or $dup -ne 1 -or $parse -ne 0 -or -not $report.validation.success -or $seeded.Count -ne 1 -or $seeded[0].occurrence_count -ne 2) { throw 'Seeded duplicate baseline failed' }
        } else {
            if ($exit -eq 0 -or $parse -lt 1 -or $report.validation.success) { throw 'Seeded parser-failure baseline failed' }
        }
        Write-Output "SCENARIO case=$case exit=$exit files=$($report.summary.file_count) duplicates=$dup parse_failures=$parse validation_success=$($report.validation.success)"
        Write-ReportEvidence $case 'json' $json
        Write-ReportEvidence $case 'markdown' $markdown
        $completed++
    }
    if ($completed -ne 3) { throw 'Baseline scenario count mismatch' }
    Write-Output 'BASELINE_REPORT_PARITY_CAPTURE_COMPLETE scenarios=3 reports=6'
} finally {
    Set-Location -LiteralPath $start
    [Environment]::SetEnvironmentVariable('DUPLICATE_FUNCTION_OUTPUT_JSON',$oldJson,'Process')
    [Environment]::SetEnvironmentVariable('DUPLICATE_FUNCTION_OUTPUT_MARKDOWN',$oldMarkdown,'Process')
    if ($owned) { Remove-Item -LiteralPath $scratch -Recurse -Force -ErrorAction Stop }
}
Write-Output 'SCRATCH_CLEANUP_COMPLETE'

